-- Fuente: catálogo SEPOMEX (archivo Cata_logo_CP.xls). Se usa éste y no la
-- columna de la plantilla del SAT porque a esa Excel le comió los ceros a la
-- izquierda: trae "1000" donde debe decir "01000".
-- =====================================================================

